-- antique-restoration-colbyn (owner)
UPDATE businesses SET description = 'Little Treasures Antiques is an antique store located at Radin House, 55 Thomson Street, in Colbyn, Pretoria. The shop buys and sells antiques and collectibles and is known for its wide selection of clocks, with porcelain, vintage furniture, art and carpets also on offer.

Services include clock repair and servicing, as well as antique valuations, so customers can have a timepiece restored or find out what a piece is worth. The shop is wheelchair accessible at the entrance, with parking on site, and accepts credit cards, debit cards and NFC mobile payments. The shop is also available by appointment for visitors who need to visit outside its regular hours.', description_enriched_at = datetime('now') WHERE slug = 'antique-restoration-colbyn' AND description = 'Antique Restoration is a furniture restoration business in Colbyn Village Shopping Centre, Colbyn, specialising in restoring antique furniture pieces.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- annelie-grundlingh-attorneys-rietfontein (owner)
UPDATE businesses SET description = 'Prinsloo and Grundlingh Attorneys Inc. is a specialised legal practice focused on employment and dispute resolution, offering its services nationwide. The firm''s labour law work includes representing clients at all Bargaining Councils, the Labour Court and private arbitrations. It also drafts employment contracts, workplace policies and disciplinary codes.

The practice chairs internal disciplinary hearings and acts as an employer or employee representative during employment disputes. Its work also covers workplace retrenchments, civil litigation and family law matters, including post-divorce property changes. Since June 2025 the firm has operated from Centurion under its current name. Consultations are available for labour law disputes and contract drafting.', description_enriched_at = datetime('now') WHERE slug = 'annelie-grundlingh-attorneys-rietfontein' AND description = 'Annelie Grundlingh Attorneys is a legal practice based in Rietfontein, Pretoria, offering attorney services to clients in the surrounding area.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
